{{ config(
            materialized='table',
                post_hook={
                    "sql": "-- v2 - coalescing shopify and meta ad id and adset id but didnt work due to the effective status filter -- v3 - matching filtered shopify orders (filtered due to missing data from meta) with historical meta data (assuming ad exists from before) -- as a fallback logic only for the filtered orders, not for all. -- v4 - restructed the code and added order level table for debugging. CREATE OR REPLACE TABLE ftune-wh.maplemonk.shopify_orders_custom as SELECT order_id, DATE(order_timestamp) AS date, order_timestamp, CAST(final_utm_campaign AS STRING) AS campaign_id, CAST(final_utm_term AS STRING) AS adset_id, CAST(final_utm_content AS STRING) AS ad_id, SUM(total_sales) AS order_value, MAX(SHOPIFY_NEW_CUSTOMER_FLAG) AS SHOPIFY_NEW_CUSTOMER_FLAG, MAX(customer_id) AS customer_id, MAX(final_utm_source) AS final_utm_source, MAX(final_utm_campaign) AS final_utm_campaign_raw, MAX(final_utm_term) AS final_utm_term_raw, MAX(final_utm_content) AS final_utm_content_raw FROM ftune-wh.maplemonk.ftune_wh_SHOPIFY_FACT_ITEMS WHERE final_utm_content In (select distinct ad_id from maplemonk.ftune_wh_MARKETING_CONSOLIDATED ) GROUP BY 1, 2, 3, 4, 5, 6 ; CREATE OR REPLACE TABLE ftune-wh.maplemonk.shopify_agg_custom AS SELECT date, campaign_id, adset_id, ad_id, COUNT(distinct order_id) AS orders, SUM(order_value) AS revenue, COUNTIF(SHOPIFY_NEW_CUSTOMER_FLAG = \'NEW\') AS new_customer_orders, SUM(CASE WHEN SHOPIFY_NEW_CUSTOMER_FLAG = \'NEW\' THEN order_value END) AS new_customer_revenue FROM ftune-wh.maplemonk.shopify_orders_custom GROUP BY 1, 2, 3, 4 ; CREATE OR REPLACE TABLE ftune-wh.maplemonk.marketing_custom AS SELECT DATE, CAST(CAMPAIGN_ID AS STRING) AS campaign_id, CAST(ADSET_ID AS STRING) AS adset_id, CAST(AD_ID AS STRING) AS ad_id, CAMPAIGN_NAME, ADSET_NAME, AD_NAME, SUM(SPEND) AS spend, SUM(CLICKS) AS clicks, SUM(IMPRESSIONS) AS impressions, status, effective_status FROM ftune-wh.maplemonk.ftune_wh_MARKETING_CONSOLIDATED where lower(channel) like \'%facebook%\' GROUP BY 1,2,3,4,5,6,7, status, effective_status ; CREATE OR REPLACE TABLE ftune-wh.maplemonk.historical_ads_custom AS SELECT DISTINCT CAST(AD_ID AS STRING) AS ad_id, ANY_VALUE(CAMPAIGN_ID) AS campaign_id, ANY_VALUE(ADSET_ID) AS adset_id, ANY_VALUE(CAMPAIGN_NAME) AS campaign_name, ANY_VALUE(ADSET_NAME) AS adset_name, ANY_VALUE(AD_NAME) AS ad_name FROM ftune-wh.maplemonk.ftune_wh_MARKETING_CONSOLIDATED where lower(channel) like \'%facebook%\' GROUP BY 1 ; CREATE OR REPLACE TABLE ftune-wh.maplemonk.ftune_wh_AD_PERFORMANCE AS SELECT COALESCE(s.DATE, m.date) AS date, COALESCE(s.campaign_id, m.campaign_id, h.campaign_id) AS campaign_id, COALESCE(s.adset_id, m.adset_id, h.adset_id) AS adset_id, COALESCE(s.ad_id, m.ad_id, h.ad_id) AS ad_id, COALESCE(m.CAMPAIGN_NAME, h.CAMPAIGN_NAME) as CAMPAIGN_NAME, COALESCE(m.ADSET_NAME, h.ADSET_NAME) as ADSET_NAME, COALESCE(m.AD_NAME, h.AD_NAME) as AD_NAME, m.spend, m.clicks, m.impressions, m.status, m.effective_status, s.orders AS shopify_attributed_orders, s.revenue AS shopify_attributed_revenue, s.new_customer_orders, s.new_customer_revenue, SAFE_DIVIDE(s.revenue, m.spend) AS shopify_attributed_roas, SAFE_DIVIDE(m.spend, IFNULL(s.orders, 0)) AS cpa, SAFE_DIVIDE(s.revenue, IFNULL(s.orders, 0)) AS aov, SAFE_DIVIDE(IFNULL(s.orders, 0), m.clicks) AS conversion_rate, SAFE_DIVIDE(s.new_customer_revenue, m.spend) AS new_customer_roas, CASE WHEN m.ad_id IS NOT NULL THEN \'Exact Match\' WHEN m.ad_id IS NULL AND h.ad_id IS NOT NULL THEN \'Recovered (Historical)\' ELSE \'Unmatched\' END AS match_type, CASE WHEN m.effective_status = \'ACTIVE\' THEN \'Active\' WHEN m.effective_status = \'PAUSED\' THEN \'Paused\' WHEN m.effective_status = \'ADSET_PAUSED\' THEN \'Paused (Adset)\' WHEN m.effective_status = \'CAMPAIGN_PAUSED\' THEN \'Paused (Campaign)\' WHEN m.effective_status IS NULL AND h.ad_id IS NOT NULL THEN \'No Meta Data (Recovered)\' WHEN m.effective_status IS NULL THEN \'No Meta Data\' ELSE m.effective_status END AS ad_status, CASE WHEN m.effective_status = \'ACTIVE\' THEN \'Active\' WHEN m.effective_status != \'ACTIVE\' AND (s.orders > 0 OR s.revenue > 0) THEN \'Inactive but Has Orders\' WHEN m.effective_status IS NULL AND h.ad_id IS NOT NULL THEN \'Recovered Order\' ELSE \'Other\' END AS performance_status FROM ftune-wh.maplemonk.shopify_agg_custom s full outer JOIN ftune-wh.maplemonk.marketing_custom m ON m.DATE = s.date AND m.AD_ID = s.ad_id LEFT JOIN ftune-wh.maplemonk.historical_ads_custom h ON s.ad_id = h.ad_id AND m.ad_id IS NULL WHERE (m.effective_status = \'ACTIVE\') OR (m.effective_status != \'ACTIVE\' AND (s.orders > 0 OR s.revenue > 0)) OR (m.ad_id IS NULL AND h.ad_id IS NOT NULL) ; CREATE OR REPLACE TABLE ftune-wh.maplemonk.ftune_wh_AD_PERFORMANCE_ORDER_DETAIL AS SELECT s.order_id, s.date, s.order_timestamp, s.campaign_id, s.adset_id, s.ad_id, s.order_value, s.SHOPIFY_NEW_CUSTOMER_FLAG, s.customer_id, s.final_utm_source, s.final_utm_campaign_raw, s.final_utm_term_raw, s.final_utm_content_raw, m.CAMPAIGN_NAME, m.ADSET_NAME, m.AD_NAME, m.spend, m.clicks, COALESCE(m.CAMPAIGN_NAME, h.campaign_name) AS final_campaign_name, COALESCE(m.ADSET_NAME, h.adset_name) AS final_adset_name, COALESCE(m.AD_NAME, h.ad_name) AS final_ad_name, CASE WHEN m.ad_id IS NOT NULL THEN \'Exact Match\' WHEN m.ad_id IS NULL AND h.ad_id IS NOT NULL THEN \'Recovered (Historical)\' ELSE \'Unmatched\' END AS match_status FROM ftune-wh.maplemonk.shopify_orders_custom s LEFT JOIN ftune-wh.maplemonk.marketing_custom m ON m.DATE = s.date AND m.AD_ID = s.ad_id LEFT JOIN ftune-wh.maplemonk.historical_ads_custom h ON s.ad_id = h.ad_id AND m.ad_id IS NULL WHERE (m.effective_status = \'ACTIVE\') OR (m.effective_status != \'ACTIVE\' AND (s.order_id IS NOT NULL OR s.order_value > 0)) OR (m.ad_id IS NULL AND h.ad_id IS NOT NULL) ORDER BY s.date DESC, s.order_timestamp DESC ; CREATE OR REPLACE TABLE ftune-wh.maplemonk.ftune_wh_SHOPIFY_ATTRIBUTED_ORDERS AS with marketing_names as ( SELECT DISTINCT CAST(CAMPAIGN_ID AS STRING) AS campaign_id, CAMPAIGN_NAME, CAST(ADSET_ID AS STRING) AS adset_id, ADSET_NAME, CAST(AD_ID AS STRING) AS ad_id, AD_NAME FROM ftune-wh.maplemonk.ftune_wh_MARKETING_CONSOLIDATED_INTERMEDIATE ) SELECT DATE(order_timestamp) AS order_date, o.order_id, o.order_name, CAST(final_utm_campaign AS STRING) AS campaign_id, CAST(final_utm_term AS STRING) AS adset_id, CAST(final_utm_content AS STRING) AS ad_id, COALESCE(c.order_status, o.order_status) AS order_status, COALESCE(c.shipping_status, \'NA\') AS shipping_status, SUM(total_sales) AS order_revenue, n.CAMPAIGN_NAME, n.ADSET_NAME, n.AD_NAME FROM ftune-wh.maplemonk.ftune_wh_SHOPIFY_FACT_ITEMS o left join (select * from ( select * ,row_number()over(partition by reference_code, Marketplace_LineItem_ID order by last_update_date desc) rw from Maplemonk.ftune_wh_EasyEcom_FACT_ITEMS ) z where z.rw = 1 and lower(marketplace) like any (\'%shopify%\') ) c on replace(o.order_name,\'#\',\'\') = c.reference_code and o.LINE_ITEM_ID=c.Marketplace_LineItem_ID LEFT JOIN marketing_names n ON CAST(o.final_utm_campaign AS STRING) = n.campaign_id AND CAST(o.final_utm_term AS STRING) = n.adset_id AND CAST(o.final_utm_content AS STRING) = n.ad_id WHERE final_utm_campaign IS NOT NULL GROUP BY 1,2,3,4,5,6,7,8,10,11,12;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            